import{at as e,it as t,n,vt as r}from"./chunks/framework.CumX-F4X.js";var i=JSON.parse(`{"title":"NuGet trusted publishing","description":"","frontmatter":{},"headers":[],"relativePath":"trusted-publishing.md","filePath":"trusted-publishing.md"}`),a={name:`trusted-publishing.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="nuget-trusted-publishing" tabindex="-1">NuGet trusted publishing <a class="header-anchor" href="#nuget-trusted-publishing" aria-label="Permalink to “NuGet trusted publishing”">​</a></h1><p>The RDP Package workflow builds and tests both target frameworks, then publishes the resulting package on pushes to main. Pull requests only build, test, and upload an artifact.</p><h2 id="nuget-org-policy" tabindex="-1">NuGet.org policy <a class="header-anchor" href="#nuget-org-policy" aria-label="Permalink to “NuGet.org policy”">​</a></h2><p>Sign in to <a href="https://www.nuget.org/" target="_blank" rel="noreferrer">NuGet.org</a>, open your profile menu, select <strong>Trusted Publishing</strong>, and add a GitHub Actions policy with these settings:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Package owner</td><td>The NuGet user or organization that owns RoyalApps.Community.Rdp.WinForms</td></tr><tr><td>Repository owner</td><td>royalapplications</td></tr><tr><td>Repository</td><td>royalapps-community-rdp</td></tr><tr><td>Workflow file</td><td>publish.yml</td></tr><tr><td>Environment</td><td>Leave empty</td></tr><tr><td>Package scope / glob pattern</td><td>RoyalApps.Community.Rdp.WinForms</td></tr><tr><td>Allowed operation</td><td>Publish new versions of existing packages</td></tr></tbody></table><p>Enter only the workflow filename, without the .github/workflows/ prefix. When selecting an organization as the package owner, create the policy using an active member account.</p><h2 id="github-configuration" tabindex="-1">GitHub configuration <a class="header-anchor" href="#github-configuration" aria-label="Permalink to “GitHub configuration”">​</a></h2><p>In the repository&#39;s <strong>Settings &gt; Secrets and variables &gt; Actions &gt; Variables</strong>, configure a repository variable named <strong>NUGET_USER</strong> with value <strong>StefanKoell</strong>. This is the NuGet.org profile username of the account that created the policy, including when the policy belongs to an organization. The workflow reads vars.NUGET_USER, matching RoyalTerminal. A secret with the same name is a separate setting and is not used.</p><p>No GitHub environment is configured by this workflow, so leave the policy&#39;s environment field empty.</p><h2 id="first-publish" tabindex="-1">First publish <a class="header-anchor" href="#first-publish" aria-label="Permalink to “First publish”">​</a></h2><ol><li>Create the NuGet policy and the NUGET_USER variable before pushing the workflow change to main.</li><li>Push the change. The publish job runs only after the build and tests succeed. NuGet/login exchanges the GitHub identity token for a temporary publishing key immediately before pushing the downloaded package.</li><li>Check that the NuGet login and Publish package steps succeed. Existing package versions are skipped; the project must have a new version to upload a release.</li><li>After successful verification, remove the old NUGET_API_KEY GitHub secret and revoke the corresponding long-lived API key on NuGet.org if no other workflow uses it.</li></ol><p>The policy identifies this repository and workflow, not a particular branch. The workflow condition limits automatic publishing to pushes to main.</p><p>See the <a href="https://learn.microsoft.com/en-us/nuget/nuget-org/trusted-publishing" target="_blank" rel="noreferrer">official NuGet trusted publishing documentation</a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};